const FIELD_CLASS =
  "h-9 w-full min-w-0 rounded-[10px] border border-border bg-input text-sm text-foreground tabular-nums outline-none transition-colors focus-visible:border-ring focus-visible:ring-2 focus-visible:ring-ring/50 disabled:cursor-not-allowed";

/** A horizontal shake for rejected input; dropped under reduced motion. */
function useRejectShake() {
  const [scope, animate] = useAnimate<HTMLDivElement>();
  const reduce = useReducedMotion();
  return {
    scope,
    shake: () => {
      if (reduce || !scope.current) return;
      animate(scope.current, { x: [0, -5, 5, -3, 3, 0] }, { duration: 0.3 });
    },
  };
}

export interface ColorPickerHexInputProps extends Omit<
  ComponentPropsWithRef<"input">,
  "value" | "defaultValue" | "type"
> {}

/** Hex field. Updates live once six or eight digits are typed, reverts invalid input on blur. */
export function ColorPickerHexInput({
  className,
  onChange,
  onBlur,
  onKeyDown,
  "aria-label": ariaLabel = "Hex color",
  ...props
}: ColorPickerHexInputProps) {
  const { hsva, hex, update, commit, disabled } = usePickerContext(
    "ColorPickerHexInput",
  );
  const [draft, setDraft] = useState<string | null>(null);
  const { scope, shake } = useRejectShake();

  const settle = () => {
    if (draft === null) return;
    const parsed = parseHex(draft);
    if (parsed) {
      update(rgbaToHsva(parsed, hsva));
      commit();
    } else shake();
    setDraft(null);
  };

  return (
    <div ref={scope} className={cn("relative min-w-0 flex-1", className)}>
      <span
        aria-hidden="true"
        className="pointer-events-none absolute top-1/2 left-3 -translate-y-1/2 text-sm text-muted-foreground font-mono"
      >
        #
      </span>
      <input
        {...props}
        type="text"
        inputMode="text"
        autoComplete="off"
        spellCheck={false}
        maxLength={9}
        disabled={disabled}
        aria-label={ariaLabel}
        value={draft ?? hex.slice(1).toUpperCase()}
        onChange={(event) => {
          onChange?.(event);
          const next = event.target.value.replace(/^#/, "");
          setDraft(next);
          // Live preview only for full-length entries, so "abc" mid-way to
          // "abcdef" does not flash a short-form color.
          if (next.length === 6 || next.length === 8) {
            const parsed = parseHex(next);
            if (parsed) update(rgbaToHsva(parsed, hsva));
          }
        }}
        onBlur={(event) => {
          onBlur?.(event);
          settle();
        }}
        onKeyDown={(event) => {
          onKeyDown?.(event);
          if (event.key === "Enter") settle();
          if (event.key === "Escape" && draft !== null) {
            event.preventDefault();
            setDraft(null);
          }
        }}
        className={cn(FIELD_CLASS, "pr-3 pl-6 font-mono uppercase text-xs")}
      />
    </div>
  );
}

type ChannelSpec = {
  key: string;
  short: string;
  name: string;
  max: number;
  value: number;
  set: (n: number) => Hsva;
};

function ChannelField({ spec }: { spec: ChannelSpec }) {
  const { update, commit, disabled } = usePickerContext("ColorPickerChannels");
  const [draft, setDraft] = useState<string | null>(null);
  const shown = Math.round(spec.value);

  return (
    <label className="flex min-w-0 flex-1 flex-col items-center gap-1">
      <input
        type="text"
        inputMode="numeric"
        autoComplete="off"
        disabled={disabled}
        aria-label={spec.name}
        value={draft ?? String(shown)}
        onChange={(event) => {
          const next = event.target.value.replace(/[^\d]/g, "").slice(0, 3);
          setDraft(next);
          if (next !== "") update(spec.set(clamp(Number(next), 0, spec.max)));
        }}
        onBlur={() => {
          if (draft !== null) commit();
          setDraft(null);
        }}
        onKeyDown={(event) => {
          const delta =
            event.key === "ArrowUp" ? 1 : event.key === "ArrowDown" ? -1 : 0;
          if (delta) {
            event.preventDefault();
            setDraft(null);
            update(
              spec.set(
                clamp(shown + delta * (event.shiftKey ? 10 : 1), 0, spec.max),
              ),
            );
            commit();
          } else if (event.key === "Enter") {
            setDraft(null);
            commit();
          }
        }}
        className={cn(FIELD_CLASS, "px-1 text-center font-mono text-xs")}
      />
      <span
        aria-hidden="true"
        className="text-[10px] font-medium text-muted-foreground"
      >
        {spec.short}
      </span>
    </label>
  );
}

export interface ColorPickerChannelsProps extends Omit<
  ComponentPropsWithRef<"div">,
  "children"
> {
  /** Which channels to edit. Default "rgb". */
  format?: "rgb" | "hsl";
}

/** Numeric RGB or HSL fields, plus an opacity field when alpha is enabled. Arrow keys nudge. */
export function ColorPickerChannels({
  format = "rgb",
  className,
  ...props
}: ColorPickerChannelsProps) {
  const { hsva, rgba, alpha } = usePickerContext("ColorPickerChannels");
  const fromRgb = (patch: Partial<Rgba>) =>
    rgbaToHsva({ ...rgba, ...patch }, hsva);
  let specs: ChannelSpec[];
  if (format === "hsl") {
    const hsl = hsvToHsl(hsva);
    specs = [
      {
        key: "h",
        short: "H",
        name: "Hue",
        max: 360,
        value: hsl.h,
        set: (n) => hslToHsv(n, hsl.s, hsl.l, hsva, hsva.a),
      },
      {
        key: "s",
        short: "S",
        name: "Saturation",
        max: 100,
        value: hsl.s,
        set: (n) => hslToHsv(hsl.h, n, hsl.l, hsva, hsva.a),
      },
      {
        key: "l",
        short: "L",
        name: "Lightness",
        max: 100,
        value: hsl.l,
        set: (n) => hslToHsv(hsl.h, hsl.s, n, hsva, hsva.a),
      },
    ];
  } else {
    specs = [
      {
        key: "r",
        short: "R",
        name: "Red",
        max: 255,
        value: rgba.r,
        set: (n) => fromRgb({ r: n }),
      },
      {
        key: "g",
        short: "G",
        name: "Green",
        max: 255,
        value: rgba.g,
        set: (n) => fromRgb({ g: n }),
      },
      {
        key: "b",
        short: "B",
        name: "Blue",
        max: 255,
        value: rgba.b,
        set: (n) => fromRgb({ b: n }),
      },
    ];
  }
  if (alpha) {
    specs.push({
      key: "a",
      short: "A",
      name: "Opacity percent",
      max: 100,
      value: hsva.a * 100,
      set: (n) => ({ ...hsva, a: n / 100 }),
    });
  }
  return (
    <div {...props} className={cn("flex min-w-0 flex-1 gap-1.5", className)}>
      {specs.map((spec) => (
        <ChannelField key={`${format}-${spec.key}`} spec={spec} />
      ))}
    </div>
  );
}

