type EyeDropperConstructor = new () => {
  open: () => Promise<{ sRGBHex: string }>;
};

export interface ColorPickerEyeDropperProps extends Omit<
  ComponentPropsWithRef<"button">,
  "type"
> {
  children?: ReactNode;
}

/** Samples a color from the screen. Renders nothing where the EyeDropper API is missing. */
export function ColorPickerEyeDropper({
  className,
  children,
  onClick,
  "aria-label": ariaLabel = "Pick a color from the screen",
  ...props
}: ColorPickerEyeDropperProps) {
  const { hsva, update, commit, disabled } = usePickerContext(
    "ColorPickerEyeDropper",
  );
  const reduce = useReducedMotion();
  const [EyeDropper, setEyeDropper] = useState<EyeDropperConstructor | null>(
    null,
  );
  useEffect(() => {
    const ctor = (window as Window & { EyeDropper?: EyeDropperConstructor })
      .EyeDropper;
    if (ctor) setEyeDropper(() => ctor);
  }, []);
  if (!EyeDropper) return null;

  return (
    <motion.button
      {...(props as React.ComponentProps<typeof motion.button>)}
      type="button"
      disabled={disabled}
      aria-label={ariaLabel}
      whileTap={reduce || disabled ? undefined : { scale: 0.92 }}
      transition={SPRING_PRESS}
      onClick={async (event) => {
        onClick?.(event);
        if (event.defaultPrevented) return;
        try {
          const { sRGBHex } = await new EyeDropper().open();
          const parsed = parseHex(sRGBHex);
          if (!parsed) return;
          update(rgbaToHsva({ ...parsed, a: hsva.a }, hsva));
          commit();
        } catch {
          // Dismissed with Escape.
        }
      }}
      className={cn(
        "inline-flex size-9 shrink-0 items-center justify-center rounded-[10px] border border-border bg-secondary text-muted-foreground outline-none transition-colors hover:text-foreground hover:border-ring focus-visible:ring-2 focus-visible:ring-ring disabled:cursor-not-allowed cursor-pointer",
        className,
      )}
    >
      {children ?? <Pipette aria-hidden="true" size={18} className="size-[18px]" />}
    </motion.button>
  );
}

